#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

volatile sig_atomic_t signaled = 0;

/* The user-defined signal handler */
void handler(int sig) {
    // Upon exit from this function, the kernel/libc trampoline 
    // will invoke sigreturn(2) to restore CPU registers and context.
    printf("[Handler] Received signal %d. Preparing to return...\n", sig);
    signaled = 1;
}

int main() {
    struct sigaction sa;
    pid_t my_pid = getpid();

    // 1. Set up the signal handler for SIGUSR1
    sa.sa_handler = handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0; 

    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    printf("PID: %d. Waiting for SIGUSR1...\n", my_pid);

    // 2. Child process sends the signal to the parent
    if (fork() == 0) {
        sleep(1);
        kill(my_pid, SIGUSR1);
        exit(0);
    }

    // 3. Parent loops, execution is interrupted by SIGUSR1.
    // sigreturn is implicitly used when the handler exits.
    printf("[Main] Entering loop.\n");
    while (signaled == 0) {
        // This sleep/loop is interrupted by the signal.
        usleep(100000); 
    }

    printf("[Main] Execution successfully resumed after signal handling mechanism finished.\n");

    return EXIT_SUCCESS;
}
